template <typename Ctx> inline bool SquadNumber( const Ctx & ctx, TableNumbering & numbering, const Squad & value );
template <typename Ctx> inline int64_t SquadPackMeasure( const Ctx & ctx, TablePackMap & seen, const Squad & value );
