// DepthLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t DepthLoadMeasure( const uint8_t * wire_file, int64_t wire_file_bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    if ( TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes ) != TableOpenOk ) { return -1; }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY
    // IS MALFORMED (docs/SPEC-TABLES.md §3): the two ends of the file have
    // met, nothing is decoded, and no region is sized from it.
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) ) { return -1; }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    int64_t root_extent = 0;
    if ( !DepthWireExtent( wire, wire_bytes, root_extent, &ids_table ) ) { return -1; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Depth ) ) + root_extent );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = DepthNodeStorage( type_id, length );
        if ( storage == kTableNodeRefused ) { return -1; } // an N the record's framing cannot carry (§2.8)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// DepthLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Depth * DepthLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, then the trailer, and only then a body:
    // a file that is both a newer form and damaged is a REFUSAL and never
    // damage (docs/SPEC-TABLES.md §3).
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; if ( wire_file_bytes > 0 && wire_file[0] == kTableWireMessageForm ) { out->reason = message_form_as_file; } else { out->reason = newer_form; } }
        return NULL;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return NULL;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Depth ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    int64_t root_extent = 0;
    if ( !DepthWireExtent( wire, wire_bytes, root_extent, &ids_table ) ) { out->malformed = true; return NULL; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Depth ) ) + root_extent );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = DepthNodeStorage( type_id, length );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x3231d0dc6fe30d4aull;
    Depth * root = new ( region ) Depth; // lifetime only: LoadBody's first act is DepthReset
    DepthReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Depth ) ) + root_extent );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = DepthNodeStorage( type_id, length );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                DepthNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                DepthNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableMapCarve root_carve;
    root_carve.at = region + TableAlignUp64( (int64_t) sizeof( Depth ) );
    root_carve.left = root_extent;
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    DepthLoadBody( r, nodes, *root );
    return root;
}

// DepthLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t DepthLoadMeasure( const TableVocabulary & vocabulary, const uint8_t * message, int64_t message_bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    if ( message_bytes < 1 || message[0] != kTableWireMessageForm || !vocabulary.announced ) { return -1; }
    const TableIdTable & ids_table = vocabulary.table;
    const uint8_t * const wire = message + 1;
    const int64_t wire_bytes = message_bytes - 1;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored, &ids_table );
    int64_t root_extent = 0;
    if ( !DepthWireExtent( wire, wire_bytes, root_extent, &ids_table ) ) { return -1; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Depth ) ) + root_extent );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = DepthNodeStorage( type_id, length );
        if ( storage == kTableNodeRefused ) { return -1; } // an N the record's framing cannot carry (§2.8)
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// DepthLoadMessage: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Depth * DepthLoadMessage( uint8_t * region, int64_t region_bytes, const TableVocabulary & vocabulary, const uint8_t * message, int64_t message_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    // THE FORM BYTE IS READ FIRST, and then the connection's own table:
    // a message with no table is REFUSED BY NAME, nothing is decoded, no
    // counter moves and malformed does not fire (docs/SPEC-TABLES.md §3.3).
    if ( message_bytes < 1 ) { out->malformed = true; return NULL; }
    if ( message[0] != kTableWireMessageForm ) { out->refused = true; out->reason = newer_form; return NULL; }
    if ( !vocabulary.announced ) { out->refused = true; out->reason = no_vocabulary; return NULL; }
    const TableIdTable & ids_table = vocabulary.table;
    const uint8_t * const wire = message + 1;
    const int64_t wire_bytes = message_bytes - 1;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Depth ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    int64_t root_extent = 0;
    if ( !DepthWireExtent( wire, wire_bytes, root_extent, &ids_table ) ) { out->malformed = true; return NULL; }
    int64_t data = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Depth ) ) + root_extent );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = DepthNodeStorage( type_id, length );
            if ( storage == kTableNodeRefused ) { out->malformed = true; return NULL; }
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x3231d0dc6fe30d4aull;
    Depth * root = new ( region ) Depth; // lifetime only: LoadBody's first act is DepthReset
    DepthReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t used = TableAlignUp64( TableAlignUp64( (int64_t) sizeof( Depth ) ) + root_extent );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = DepthNodeStorage( type_id, length );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                DepthNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                DepthNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableMapCarve root_carve;
    root_carve.at = region + TableAlignUp64( (int64_t) sizeof( Depth ) );
    root_carve.left = root_extent;
    nodes.carve = &root_carve; // the ROOT's extent is its own, like every node's
    DepthLoadBody( r, nodes, *root );
    return root;
}

// DepthLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool DepthLoadBuilder( DepthBuilder & builder, const uint8_t * wire_file, int64_t wire_file_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    TableIdTable ids_table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( wire_file, wire_file_bytes, ids_table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        if ( verdict == TableOpenDamaged ) { out->malformed = true; } else { out->refused = true; }
        return false;
    }
    if ( TableBodyEndsEarly( wire_file + 1, body_bytes, ids_table ) )
    {
        out->malformed = true; // a byte no field claims, before the table (§3)
        return false;
    }
    const uint8_t * const wire = wire_file + 1;
    const int64_t wire_bytes = body_bytes;
    Depth * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting, &ids_table );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0x3231d0dc6fe30d4aull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    nodes.worker = &builder.main; // and a map's entries are the arena's, not a node extent's (§2.8)
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = DepthNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out, &ids_table );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out, &ids_table );
                DepthNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out, &ids_table );
    r.nested = false; // the ROOT body, the one that carries the node table
    TableMapCarve root_carve;
    root_carve.worker = &builder.main;
    nodes.carve = &root_carve;
    bool ok = DepthLoadBody( r, nodes, *root );
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- the cooked form: point at a cook (docs/SPEC-TABLES.md §7) ----

// SquadOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// A REFERENCE INSIDE THE REGION IS DEREFERENCED THROUGH SquadAt: the slot holds
// the signed self-relative byte delta of §6.3, so a deref is one add and
// needs no base pointer, a whole region relocates by plain memcpy, and a
// delta of zero is null.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Squad * SquadOpen( const void * bytes, uint64_t length )
{
    return (const Squad *) TableCookOpen( bytes, length, (uint64_t) sizeof( Squad ), (uint64_t) alignof( Squad ) );
}

// DepthOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// A REFERENCE INSIDE THE REGION IS DEREFERENCED THROUGH DepthAt: the slot holds
// the signed self-relative byte delta of §6.3, so a deref is one add and
// needs no base pointer, a whole region relocates by plain memcpy, and a
// delta of zero is null.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Depth * DepthOpen( const void * bytes, uint64_t length )
{
    return (const Depth *) TableCookOpen( bytes, length, (uint64_t) sizeof( Depth ), (uint64_t) alignof( Depth ) );
}

// ---- the cooked form: WRITE a cook (docs/SPEC-TABLES.md §7.6) ----
//
// The bytes are `schema cook`'s, and the tool stays the reference: the two
// writers are held to one file, byte for byte, in both byte orders. A cook is
// content-addressed by (asset hash, build version), so two writers of one
// instance produce ONE artifact or the pair means nothing.

inline void SquadRosterEntryCookBody( uint8_t * at, const SquadRosterEntry & value, TableByteOrder order );
template <typename Ctx> inline bool SquadCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Squad & value, TableByteOrder order );
template <typename Ctx> inline bool DepthCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Depth & value, TableByteOrder order );

inline void SquadRosterEntryCookBody( uint8_t * at, const SquadRosterEntry & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.key, 1, order );
    ItemCookBody( at + 4, value.value, order );
}

template <typename Ctx> inline bool SquadCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Squad & value, TableByteOrder order )
{
    (void) ctx; (void) region; // no reference below this node: the class was decided by a pointer elsewhere in its closure
    (void) value;
    table_cook_put( at + 0, 0, 8, order ); // roster: the entry array's delta, filled by the extent writer
    table_cook_put( at + 8, 0, 4, order ); // and its count
    return true;
}

template <typename Ctx> inline bool DepthCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Depth & value, TableByteOrder order )
{
    if ( !SquadCookBody( ctx, region, at + 0, value.one, order ) ) { return false; }
    // all 3 slots: the storage is allocate-max, and a slot past the count rides as it lies (§7.2)
    for ( int32_t i = 0; i < 3; i++ )
    {
        if ( !SquadCookBody( ctx, region, at + 16 + i * 16, value.many[ i ], order ) ) { return false; }
    }
    table_cook_put( at + 64, (uint64_t) (uint32_t) value.many_count, 4, order );
    // [Slot]: E.Max slots at the SHIFTED positions the storage has (§2.4, §7.2)
    for ( int32_t i = 0; i < 2; i++ )
    {
        if ( !SquadCookBody( ctx, region, at + 72 + i * 16, value.keyed.slots[ i ], order ) ) { return false; }
    }
    {
        table_cook_put( at + 104, (uint64_t) value.arm.type, 1, order ); // the tag; None is the tag alone
        switch ( value.arm.type )
        {
            case ForceType::Squad: if ( !SquadCookBody( ctx, region, at + 104 + 8, value.arm.squad, order ) ) { return false; } break;
            case ForceType::Plain:
            {
                table_cook_put( at + 104 + 8, (uint64_t) value.arm.plain, 4, order );
                break;
            }
            default: break; // every byte outside the set arm stays zero
        }
    }
    table_cook_put( at + 128, (uint64_t) value.after, 4, order );
    return true;
}

template <typename Ctx> inline bool SquadRosterEntryCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const SquadRosterEntry & value, TableByteOrder order );
template <typename Ctx> inline bool SquadCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Squad & value, TableByteOrder order );
template <typename Ctx> inline bool DepthCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Depth & value, TableByteOrder order );

// SquadRosterEntryCookMaps: SquadRosterEntry's map arrays into the node's extent, PRE-ORDER, the entries
// in ASCENDING key order, each through its own cook body (§2.8, §7.6).
template <typename Ctx> inline bool SquadRosterEntryCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const SquadRosterEntry & value, TableByteOrder order )
{
    (void) ctx; (void) region; (void) extent; (void) at; (void) record; (void) value; (void) order;
    return true; // no map below this record
}

// SquadCookMaps: Squad's map arrays into the node's extent, PRE-ORDER, the entries
// in ASCENDING key order, each through its own cook body (§2.8, §7.6).
template <typename Ctx> inline bool SquadCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Squad & value, TableByteOrder order )
{
    (void) region; // a map's entries carry their own references through their own bodies
    { // roster
        TableMapCursor<SquadRosterEntry> cursor = TableMapOrder( ctx, value.roster );
        if ( !cursor.ok ) { return false; }
        at = ( at + 3 ) & ~(int64_t) 3; // at alignof( SquadRosterEntry )
        uint8_t * array = extent + at;
        at += (int64_t) cursor.count * 8; // the whole array FIRST
        // the SIXTEEN BYTES of the slot: the self-relative delta, then the count
        table_cook_put( record + 0, cursor.count > 0 ? (uint64_t) (int64_t) ( array - ( record + 0 ) ) : 0, 8, order );
        table_cook_put( record + 8, (uint64_t) (uint32_t) cursor.count, 4, order );
        for ( int32_t i = 0; i < cursor.count; i++ )
        {
            SquadRosterEntryCookBody( array + i * 8, *cursor[i], order );
        }
        TableMapRelease( cursor );
    }
    return true;
}

// DepthCookMaps: Depth's map arrays into the node's extent, PRE-ORDER, the entries
// in ASCENDING key order, each through its own cook body (§2.8, §7.6).
template <typename Ctx> inline bool DepthCookMaps( const Ctx & ctx, const TableCookRegion & region, uint8_t * extent, int64_t & at, uint8_t * record, const Depth & value, TableByteOrder order )
{
    (void) region; // a map's entries carry their own references through their own bodies
    if ( !SquadCookMaps( ctx, region, extent, at, record + 0, value.one, order ) ) { return false; } // one
    for ( int32_t i = 0; i < ( value.many_count < 3 ? value.many_count : 3 ); i++ ) // many
    {
        if ( !SquadCookMaps( ctx, region, extent, at, record + 16 + i * 16, value.many[i], order ) ) { return false; }
    }
    for ( int32_t i = 0; i < 2; i++ ) // keyed
    {
        if ( !SquadCookMaps( ctx, region, extent, at, record + 72 + i * 16, value.keyed.slots[i], order ) ) { return false; }
    }
    return true;
}

// SquadRosterEntryCookNode: one node — the record, then the extent its maps take (§2.8).
template <typename Ctx> inline bool SquadRosterEntryCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const SquadRosterEntry & value, TableByteOrder order )
{
    SquadRosterEntryCookBody( at, value, order );
    int64_t extent_at = 0;
    return SquadRosterEntryCookMaps( ctx, region, at + 8, extent_at, at, value, order );
}

// SquadCookNode: one node — the record, then the extent its maps take (§2.8).
template <typename Ctx> inline bool SquadCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Squad & value, TableByteOrder order )
{
    if ( !SquadCookBody( ctx, region, at, value, order ) ) { return false; }
    int64_t extent_at = 0;
    return SquadCookMaps( ctx, region, at + 16, extent_at, at, value, order );
}

// DepthCookNode: one node — the record, then the extent its maps take (§2.8).
template <typename Ctx> inline bool DepthCookNode( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Depth & value, TableByteOrder order )
{
    if ( !DepthCookBody( ctx, region, at, value, order ) ) { return false; }
    int64_t extent_at = 0;
    return DepthCookMaps( ctx, region, at + 136, extent_at, at, value, order );
}

// SquadCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
// A NODE'S SIZE DEPENDS ON ITS VALUE where a map rides in its extent
// (docs/SPEC-TABLES.md §2.8), so the layout takes the resolution context
// the numbering walked and reads the same maps that walk read.
template <typename Ctx>
inline bool SquadCookLayout( const Ctx & ctx, const Squad & root, const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    const int64_t root_extent = SquadMapExtent( ctx, root );
    if ( root_extent < 0 ) { return false; }
    int64_t offset = 16 + root_extent; // the root at zero, its extent behind it
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// SquadCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t SquadCookMeasureFrom( const Ctx & ctx, const Squad & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( SquadNumberFrom( ctx, numbering, root ) && SquadCookLayout( ctx, root, numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// SquadCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool SquadCookFrom( const Ctx & ctx, const Squad & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = SquadNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && SquadCookLayout( ctx, root, numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = SquadCookNode( ctx, region, region.base, root, order );
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0xec07a2f760550a91ull, 8, order ); // the root: fnv1a64( "Squad" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// SquadCookMeasure / SquadCook over a REGION root — a locked builder's AsConst, a
// region SquadLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t SquadCookMeasure( const Squad * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return SquadCookMeasureFrom( ctx, *root, allocator );
}

inline bool SquadCook( const Squad * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return SquadCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t SquadCookMeasure( const SquadBuilder & builder )
{
    if ( builder.region != NULL ) { return SquadCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return SquadCookMeasureFrom( ctx, *(const Squad *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool SquadCook( const SquadBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return SquadCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return SquadCookFrom( ctx, *(const Squad *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// DepthCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
// A NODE'S SIZE DEPENDS ON ITS VALUE where a map rides in its extent
// (docs/SPEC-TABLES.md §2.8), so the layout takes the resolution context
// the numbering walked and reads the same maps that walk read.
template <typename Ctx>
inline bool DepthCookLayout( const Ctx & ctx, const Depth & root, const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    const int64_t root_extent = DepthMapExtent( ctx, root );
    if ( root_extent < 0 ) { return false; }
    int64_t offset = 136 + root_extent; // the root at zero, its extent behind it
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// DepthCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t DepthCookMeasureFrom( const Ctx & ctx, const Depth & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( DepthNumberFrom( ctx, numbering, root ) && DepthCookLayout( ctx, root, numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// DepthCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool DepthCookFrom( const Ctx & ctx, const Depth & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = DepthNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && DepthCookLayout( ctx, root, numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = DepthCookNode( ctx, region, region.base, root, order );
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0x3231d0dc6fe30d4aull, 8, order ); // the root: fnv1a64( "Depth" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// DepthCookMeasure / DepthCook over a REGION root — a locked builder's AsConst, a
// region DepthLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t DepthCookMeasure( const Depth * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return DepthCookMeasureFrom( ctx, *root, allocator );
}

inline bool DepthCook( const Depth * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return DepthCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t DepthCookMeasure( const DepthBuilder & builder )
{
    if ( builder.region != NULL ) { return DepthCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return DepthCookMeasureFrom( ctx, *(const Depth *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool DepthCook( const DepthBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return DepthCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return DepthCookFrom( ctx, *(const Depth *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
// A pointer FIELD is a TableRef — eight bytes and no address — so the
// property holds in BOTH forms: a fixed-size table is one relocatable
// struct, and a packed region is one relocatable block whose references
// are self-relative and therefore survive a plain memcpy.
static_assert( __is_trivially_copyable( SquadRosterEntry ), "SquadRosterEntry must stay relocatable" );
static_assert( __is_standard_layout( SquadRosterEntry ), "SquadRosterEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Squad ), "Squad must stay relocatable" );
static_assert( __is_standard_layout( Squad ), "Squad must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Depth ), "Depth must stay relocatable" );
static_assert( __is_standard_layout( Depth ), "Depth must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( SquadRosterEntry ) == 8, "SquadRosterEntry's sizeof moved: the build version was taken over 8, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( SquadRosterEntry ) == 4, "SquadRosterEntry's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( SquadRosterEntry, key ) == 0, "SquadRosterEntry's field key moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( SquadRosterEntry, value ) == 4, "SquadRosterEntry's field value moved: the build version was taken over offset 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Squad ) == 16, "Squad's sizeof moved: the build version was taken over 16, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Squad ) == 8, "Squad's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Squad, roster ) == 0, "Squad's field roster moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Depth ) == 136, "Depth's sizeof moved: the build version was taken over 136, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Depth ) == 8, "Depth's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Depth, one ) == 0, "Depth's field one moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Depth, many ) == 16, "Depth's field many moved: the build version was taken over offset 16 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Depth, keyed ) == 72, "Depth's field keyed moved: the build version was taken over offset 72 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Depth, arm ) == 104, "Depth's field arm moved: the build version was taken over offset 104 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Depth, after ) == 128, "Depth's field after moved: the build version was taken over offset 128 (docs/SPEC-TABLES.md §20.3)" );

